DROP TABLE IF EXISTS bom_form_refs;
DROP TABLE IF EXISTS bom_documents;

CREATE TABLE IF NOT EXISTS bom_documents (
  doc_no_norm    TEXT PRIMARY KEY,
  doc_no_raw     TEXT NOT NULL,
  category       TEXT NOT NULL,
  category_label TEXT NOT NULL,
  name           TEXT NOT NULL,
  owner_dept     TEXT,
  list_rev       INTEGER,
  list_date      TEXT,
  file_rev       INTEGER,
  file_date      TEXT,
  status         TEXT NOT NULL,
  forms_count    INTEGER NOT NULL DEFAULT 0,
  sort_order     INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_bomdoc_cat ON bom_documents(category, sort_order);
CREATE INDEX IF NOT EXISTS idx_bomdoc_status ON bom_documents(status);

CREATE TABLE IF NOT EXISTS bom_form_refs (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  doc_no_norm    TEXT NOT NULL,
  form_type      TEXT NOT NULL,        -- form | variant | appendix | external_ref
  form_no_raw    TEXT,                 -- A1100-01, B2300-1, 65200-03
  form_no_norm   TEXT,                 -- 정규화: A110001, B230001, 6520003
  label          TEXT NOT NULL,        -- 원문 양식명/부표명
  sort_order     INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (doc_no_norm) REFERENCES bom_documents(doc_no_norm)
);
CREATE INDEX IF NOT EXISTS idx_bomref_doc ON bom_form_refs(doc_no_norm, sort_order);
CREATE INDEX IF NOT EXISTS idx_bomref_formno ON bom_form_refs(form_no_norm);

